import type { Combination, Position, TimelineEvent, TourStep } from '../content/schema'
// Slim slice of the content for the first screen. Generated by `npm run validate`.
import data from '../generated/core.json'

export type CorePosition = Pick<Position, 'id' | 'name' | 'shortName' | 'axis' | 'color' | 'initial' | 'tagline' | 'summary'>
export type CoreTimeline = { position: string; events: Pick<TimelineEvent, 'id' | 'milestone' | 'label' | 'at' | 'end'>[] }
export const core = data as unknown as {
  positions: CorePosition[]
  combinations: Combination[]
  tour: TourStep[]
  timelines: CoreTimeline[]
  counts: Record<'positions' | 'topics' | 'passages' | 'arguments' | 'scholars' | 'glossary' | 'sources' | 'library', number>
}

const ORDER = [
  'postmil', 'amil', 'histpremil', 'disppremil',
  'partial-preterism', 'full-preterism', 'historicism', 'futurism', 'idealism', 'eclectic',
  'covenant-theology', 'dispensationalism', 'progressive-covenantalism',
]
const rank = (id: string) => ORDER.indexOf(id) + 1 || 99
export const positionsSorted = [...core.positions].sort((a, b) => rank(a.id) - rank(b.id))
export const positionsById = new Map(core.positions.map((p) => [p.id, p]))
export const millennialViews = positionsSorted.filter((p) => p.axis === 'millennial')
export const hermeneuticViews = positionsSorted.filter((p) => p.axis === 'hermeneutic')
export const frameworkViews = positionsSorted.filter((p) => p.axis === 'framework')
/** Positions compared in the matrix and timelines. */
export const views = positionsSorted.filter((p) => p.axis !== 'framework')

export function positionName(id: string, short = false): string {
  const p = positionsById.get(id)
  return p ? (short ? p.shortName : p.name) : id
}
